operation.add:
// Translate Expert: skip the module on excluded admin routes (exact match, or prefix match with a trailing *).
// Keep these rules the same as isCurrentRouteExcluded() in admin/controller/extension/module/client_translate_expert.php (OC4).
$teDefaultRoute = version_compare(VERSION, '2.0', '<') ? 'common/home' : 'common/dashboard';
$teRoute = isset($this->request->get['route']) ? trim((string)$this->request->get['route'], " \t/") : '';
if ($teRoute === '') {
	$teRoute = $teDefaultRoute;
}
$teRoute = str_replace('|', '.', $teRoute);
$teExcluded = false;
if (strpos($teRoute, 'module/client_translate_expert') === false) {
	foreach (explode("\n", (string)$this->config->get('client_translate_expert_excluded_routes')) as $teRule) {
		$teRule = trim($teRule);
		$tePos = strpos($teRule, 'route=');
		if ($tePos !== false) {
			$teRule = substr($teRule, $tePos + 6);
		} elseif (strpos($teRule, 'index.php') !== false) {
			// An admin URL without route= opens the dashboard.
			$teRule = $teDefaultRoute;
		}
		$tePos = strpos($teRule, '&');
		if ($tePos !== false) {
			$teRule = substr($teRule, 0, $tePos);
		}
		$teRule = str_replace('|', '.', trim($teRule, " \t/"));
		if ($teRule === '') {
			continue;
		}
		if (substr($teRule, -1) === '*') {
			// A rule of only * matches all routes. Do not call strpos() with an empty needle (warning on PHP < 8).
			$tePrefix = substr($teRule, 0, -1);
			$teExcluded = $tePrefix === '' || strpos($teRoute, $tePrefix) === 0;
		} else {
			$teExcluded = $teRule === $teRoute;
		}
		if ($teExcluded) {
			break;
		}
	}
}
$data['client_translate_expert_head_html'] = '';
$data['client_translate_expert_header_html'] = '';
if (!$teExcluded) {
	$this->load->model('localisation/language');
	$teLanguages = json_encode($this->model_localisation_language->getLanguages()) ?: '{}';
	$data['client_translate_expert_head_html'] = '<script type="text/javascript" src="view/javascript/client_translate_expert.js?v={client_version}"></script>'
		. '<link type="text/css" rel="stylesheet" href="view/stylesheet/client_translate_expert.css?v={client_version}" />';
	$data['client_translate_expert_header_html'] = '<script>'
		. 'document.js_const_client_translate_expert_is_enabled = ' . (int)$this->config->get('client_translate_expert_status') . ';'
		. 'document.js_const_client_translate_expert_show_char_count_is_enabled = ' . (int)$this->config->get('client_translate_expert_show_char_count_globally') . ';'
		. 'document.js_const_client_translate_expert_languages = ' . $teLanguages . ';'
		. '</script>';
}
